select (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'songs' and column_name = 'publicada') as existe, (select data_type from information_schema.columns where table_schema = 'public' and table_name = 'songs' and column_name = 'publicada') as tipo, (select is_nullable from information_schema.columns where table_schema = 'public' and table_name = 'songs' and column_name = 'publicada') as admite_nulos, (select column_default from information_schema.columns where table_schema = 'public' and table_name = 'songs' and column_name = 'publicada') as valor_por_defecto, (select count(*) from public.songs where publicada is not true) as canciones_no_publicadas, (select count(*) from public.songs) as total
